// Generates apps/mobile/lib/app/design_tokens.g.dart from design/tokens.json so web and mobile share one token source.
import { readFile, writeFile } from 'node:fs/promises';

const tokens = JSON.parse(await readFile(new URL('../design/tokens.json', import.meta.url), 'utf8'));
const color = (hex) => `Color(0xFF${hex.replace('#', '').toUpperCase()})`;
const lines = [
  '// GENERATED by tools/generate-mobile-tokens.mjs from design/tokens.json. Do not edit by hand; run `pnpm tokens:mobile`.',
  "import 'package:flutter/painting.dart';",
  '',
  'abstract final class XinobiTokens {',
  `  static const String version = '${tokens.version}';`,
  ...Object.entries(tokens.color).map(([name, hex]) => `  static const Color ${name} = ${color(hex)};`),
  `  static const String headerFamily = '${tokens.type.headerFamily}';`,
  `  static const double headerWeight = ${tokens.type.headerWeight};`,
  "  static const String bodyFamily = 'Inter';",
  ...Object.entries(tokens.radius).map(([name, value]) => `  static const double radius${name[0].toUpperCase()}${name.slice(1)} = ${value};`),
  `  static const List<double> space = [${tokens.space.join(', ')}];`,
  `  static const double gutterMobile = ${tokens.content.gutterMobile};`,
  ...Object.entries(tokens.header).map(([name, value]) => `  static const double header${name[0].toUpperCase()}${name.slice(1)} = ${value};`),
  '}',
  '',
];
await writeFile(new URL('../apps/mobile/lib/app/design_tokens.g.dart', import.meta.url), lines.join('\n'));
